package com.vib.cms.theme.service;
import com.vib.cms.theme.api.*;import com.vib.cms.theme.repository.ThemeRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ThemeService {private final ThemeRepository repo;public ThemeService(ThemeRepository repo){this.repo=repo;}public List<ThemeResponse> list(UUID product){return repo.list(product);}public ThemeResponse get(UUID id){return repo.get(id);}@Transactional public ThemeResponse create(ThemeRequest r,String actor){return repo.create(r,actor);}@Transactional public ThemeResponse update(UUID id,ThemeRequest r,String actor){return repo.update(id,r,actor);}@Transactional public void archive(UUID id){repo.archive(id);}}
